import {npcFamilyInvites} from "./dynamic-npc-families.mjs";
// Invitations are generated by the existing living NPC cast, not a separate population.
const types={npcwedding:{name:'NPC wedding',cost:80,bond:8,important:true},npcbaby:{name:'Welcome a new family member',cost:40,bond:6,important:true},npcanniversary:{name:'NPC marriage anniversary',cost:35,bond:6,important:true},npcgathering:{name:'Family gathering',cost:25,bond:5,important:false},birthday:{name:'Milestone birthday',cost:35,bond:7,important:true},anniversary:{name:'Marriage anniversary',cost:80,bond:8,important:true},reunion:{name:'Friends reunion',cost:25,bond:5,important:false},tradition:{name:'Annual gathering',cost:30,bond:6,important:true},conversation:{name:'A request to talk',cost:0,bond:0,important:false},celebration:{name:'Personal celebration',cost:20,bond:5,important:false}};
const empty=()=>({version:1,lastYear:null,serial:0,inbox:[],history:[],traditions:[],attended:0,declined:0,missed:0,conversations:0,marriedAge:null});
const state=s=>s.socialLife||empty(),ensure=s=>(s.socialLife??=empty()),person=(s,id)=>s.people.find(p=>p.id===id&&p.alive);
const age=n=>Number.isInteger(n)&&n>=0&&n<=110;
const hash=x=>{let h=2166136261;for(const c of String(x))h=Math.imul(h^c.charCodeAt(0),16777619);return h>>>0;};
const cost=(s,t,c)=>s.age<18?0:Math.round(types[t].cost*c.cost);
function archive(s,q,row,status,ctx){q.inbox=q.inbox.filter(i=>i.id!==row.id);q.history.push({...row,status,resolvedAge:s.age});q.history=q.history.slice(-40);if(status==='attended')q.attended++;if(status==='declined')q.declined++;if(status==='missed')q.missed++;if(status==='conversation')q.conversations++;if(status!=='cancelled')ctx.add(s,types[row.kind].name+' with '+row.hostName+': '+status+'.','people');}
const availableHost=(s,row)=>{const p=person(s,row.hostId);return p&&p.bond>=25&&(row.kind!=='anniversary'||p.role==='partner'&&p.married)?p:null;};
export function socialMarriage(s){const q=ensure(s);q.marriedAge=s.age;}
export function socialSeparation(s){if(s.socialLife)s.socialLife.marriedAge=null;}
function offer(s,q,p,kind,guests=[],traditionId=null){if(q.inbox.length>=2||q.inbox.some(x=>x.hostId===p.id))return;const row={id:++q.serial,kind,hostId:p.id,hostName:p.name,age:s.age,guestIds:guests.filter(x=>x!==p.id).slice(0,3),traditionId};q.inbox.push(row);}
export function socialLifeYear(s,ctx){if(s.age<6)return;const q=ensure(s);if(q.lastYear===s.age)return;q.lastYear=s.age;
 for(const row of q.inbox.slice()){const p=availableHost(s,row);if(!p||s.justice?.years>0||s.justice?.case){archive(s,q,row,'cancelled',ctx);continue;}if(row.age<s.age){if(types[row.kind].important&&p.bond>=60)ctx.bond(s,p,-2,'Missed an important invitation without replying');archive(s,q,row,'missed',ctx);}}
 q.traditions=q.traditions.filter(t=>person(s,t.hostId)&&person(s,t.hostId).bond>=25);
 if(!s.alive||s.justice?.years>0||s.justice?.case)return;
 const people=s.people.filter(p=>p.alive&&p.age>=6&&p.bond>=45&&['friend','partner','parent','sibling','child','grandparent'].includes(p.role)).sort((a,b)=>b.bond-a.bond||a.id-b.id);
 const partner=people.find(p=>p.role==='partner'&&p.married);
 if(partner&&q.marriedAge!==null&&s.age>q.marriedAge&&(s.age-q.marriedAge)%5===0)offer(s,q,partner,'anniversary');
 for(const event of npcFamilyInvites(s)){if(!q.inbox.some(i=>i.hostId===event.host.id)&&q.inbox.length<2){offer(s,q,event.host,event.kind,event.guests);break;}}
 const birthday=people.find(p=>p.age>=10&&p.age%5===0&&!q.inbox.some(i=>i.hostId===p.id));if(birthday)offer(s,q,birthday,'birthday');
 const tradition=q.traditions.find(t=>t.nextAge<=s.age&&!q.inbox.some(i=>i.hostId===t.hostId));if(tradition){const host=person(s,tradition.hostId);if(host&&q.inbox.length<2){offer(s,q,host,'tradition',tradition.guestIds.filter(id=>person(s,id)),tradition.id);tradition.nextAge=s.age+2;}}
 const friends=people.filter(p=>p.role==='friend'),eligible=people.filter(p=>!q.inbox.some(i=>i.hostId===p.id));
 if(eligible.length&&q.inbox.length<2&&s.age%2===0){const p=eligible[hash((s.lifeId||s.name)+':social:'+s.age)%eligible.length];const kind=s.age>=13&&p.role==='friend'&&friends.length>=2?'reunion':s.age>=13&&s.age%4===0?'conversation':'celebration';offer(s,q,p,kind,kind==='reunion'?friends.filter(x=>x.id!==p.id).slice(0,3).map(x=>x.id):[]);}
 for(const i of q.inbox.filter(x=>x.age===s.age))ctx.add(s,i.hostName+' invited you to '+types[i.kind].name.toLowerCase()+'.','people');
}
export function socialLifeView(s,c){const q=state(s);return {inbox:q.inbox.map(i=>({...i,title:types[i.kind].name,important:types[i.kind].important,cost:cost(s,i.kind,c),available:!!availableHost(s,i),guests:i.guestIds.map(id=>person(s,id)?.name).filter(Boolean)})),history:q.history.slice(-8).reverse(),traditions:q.traditions.map(t=>({...t,host:person(s,t.hostId)?.name||'Unavailable',guests:t.guestIds.map(id=>person(s,id)?.name).filter(Boolean)})),attended:q.attended,declined:q.declined,missed:q.missed,conversations:q.conversations};}
export function socialLifeCommands(s,c,dialogueCommands){if(!s.alive||s.age<6||s.pending!==null||s.justice?.years>0||s.justice?.case)return [];return state(s).inbox.filter(i=>i.age===s.age).map(i=>{const p=availableHost(s,i),isTalk=i.kind==='conversation',price=cost(s,i.kind,c),canTalk=!isTalk||dialogueCommands(s).some(x=>x.id==='dialogue:open:person-'+i.hostId&&x.enabled);return {id:'socialinvite:accept:'+i.id,label:(isTalk?'Accept conversation invitation from ':'Attend '+types[i.kind].name.toLowerCase()+' with ')+i.hostName,detail:(price?'$'+price:'Free')+' · 1 activity · '+(isTalk?'Open a real conversation':'Share a meaningful occasion'),enabled:!!p&&s.actions>0&&s.cash>=price&&canTalk};});}
export function socialLifeAct(s,id,ctx,c){if(!socialLifeCommands({...s,actions:s.actions+1},c,ctx.dialogueCommands).some(x=>x.id===id&&x.enabled))throw Error('Invitation unavailable.');const q=ensure(s),row=q.inbox.find(x=>x.id===Number(id.split(':')[2])),p=availableHost(s,row);
 if(row.kind==='conversation'){ctx.beginDialogue(s,'person-'+p.id);archive(s,q,row,'conversation',ctx);return;}
 const price=cost(s,row.kind,c);if(price)ctx.spend(s,price);ctx.bond(s,p,types[row.kind].bond,types[row.kind].name+' together');for(const id of row.guestIds){const guest=person(s,id);if(guest&&guest.bond>=25)ctx.bond(s,guest,3,'Shared '+types[row.kind].name.toLowerCase());}ctx.change(s,'happiness',3);ctx.change(s,'social',2);
 if(row.kind==='reunion'&&q.traditions.length<4&&!q.traditions.some(t=>t.hostId===p.id))q.traditions.push({id:row.id,hostId:p.id,guestIds:row.guestIds.slice(),startedAge:s.age,nextAge:s.age+2});
 archive(s,q,row,'attended',ctx);
}
export function declineSocial(s,id,ctx){const q=ensure(s),row=q.inbox.find(x=>x.id===id&&x.age===s.age);if(!s.alive||!row)throw Error('Invitation unavailable.');archive(s,q,row,availableHost(s,row)?'declined':'cancelled',ctx);return s;}
const validPersonId=id=>Number.isInteger(id)&&id>0;
const group=a=>Array.isArray(a)&&a.length<=3&&a.every(validPersonId)&&new Set(a).size===a.length;
function validRow(x){return x&&Number.isInteger(x.id)&&x.id>0&&Object.hasOwn(types,x.kind)&&validPersonId(x.hostId)&&typeof x.hostName==='string'&&age(x.age)&&group(x.guestIds)&&!x.guestIds.includes(x.hostId)&&(x.traditionId===null||Number.isInteger(x.traditionId)&&x.traditionId>0);}
export function validateSocialLife(q){if(q===undefined)return true;return !!q&&q.version===1&&(q.lastYear===null||age(q.lastYear))&&(q.marriedAge===null||age(q.marriedAge))&&['serial','attended','declined','missed','conversations'].every(k=>Number.isInteger(q[k])&&q[k]>=0)&&Array.isArray(q.inbox)&&q.inbox.length<=2&&q.inbox.every(x=>validRow(x)&&x.id<=q.serial)&&new Set(q.inbox.map(x=>x.id)).size===q.inbox.length&&Array.isArray(q.history)&&q.history.length<=40&&q.history.every(x=>validRow(x)&&x.id<=q.serial&&age(x.resolvedAge)&&x.resolvedAge>=x.age&&['attended','declined','missed','cancelled','conversation'].includes(x.status))&&Array.isArray(q.traditions)&&q.traditions.length<=4&&q.traditions.every(x=>x&&Number.isInteger(x.id)&&x.id>0&&x.id<=q.serial&&validPersonId(x.hostId)&&group(x.guestIds)&&!x.guestIds.includes(x.hostId)&&age(x.startedAge)&&Number.isInteger(x.nextAge)&&x.nextAge>x.startedAge&&x.nextAge<=112)&&new Set(q.traditions.map(x=>x.hostId)).size===q.traditions.length;}
